head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldods16000";
scwin.chgBtn = null;
scwin.confBtn = null;
scwin.checkPwAjax = null;
scwin.emailCheck = null;
scwin.sendForm = null;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "__rb1", fn: function () { return String(((String(dma_dataList.get("corpUsrNm")) === "") ? String(dma_dataList.get("empNm")) : String(dma_dataList.get("corpUsrNm")))); } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { /* TODO Stage2: [sdd] 행 복사 대상 부재:  it.childId */ continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = function () {
    try {
        (($c.util.getComponent('ipt_emailYn')) && ($c.util.getComponent('ipt_emailYn')).setValue ? ($c.util.getComponent('ipt_emailYn')).setValue((true) === 'disabled' || (true) === 'readonly' || (true) === 'checked' ? true : (true)) : void 0);
        (($c.util.getComponent('ipt_phoneYn')) && ($c.util.getComponent('ipt_phoneYn')).setValue ? ($c.util.getComponent('ipt_phoneYn')).setValue((true) === 'disabled' || (true) === 'readonly' || (true) === 'checked' ? true : (true)) : void 0);

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldods16000.onpageload' }); }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.chgBtn = $c.util.getComponent('chgBtn');
        scwin.confBtn = $c.util.getComponent('confBtn');
        scwin.checkPwAjax = scwin.tx_checkPwAjax;
        scwin.emailCheck = scwin.tx_emailCheck;
        scwin.sendForm = scwin.tx_sendForm;
        await scwin.init_rowCopy();
        scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldods16000.onpageload' });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name a_3_onclick
 * @description 「home」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.a_3_onclick = function(e){
    try {

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldods16000.a_3_onclick' }); }
};

/**
 * @method
 * @name btn_chngEmailBtn_onclick
 * @description 「변경」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_chngEmailBtn_onclick = function(e){
    try {
        scwin.chngEmailBtn()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldods16000.btn_chngEmailBtn_onclick' }); }
};

/**
 * @method
 * @name btn_emailCheck_onclick
 * @description 「E-mail 중복확인」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_emailCheck_onclick = function(e){
    try {
        scwin.emailCheck()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldods16000.btn_emailCheck_onclick' }); }
};

/**
 * @method
 * @name btn_openPwPop_onclick
 * @description 「비밀번호 변경」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_openPwPop_onclick = function(e){
    try {
        scwin.openPwPop()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldods16000.btn_openPwPop_onclick' }); }
};

/**
 * @method
 * @name btn_validationForm_onclick
 * @description 「저장」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_validationForm_onclick = async function(e){
    try {
        await scwin.validationForm()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldods16000.btn_validationForm_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_checkPwAjax
 * @description check Pw Ajax 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_checkPwAjax = async function () {
    const sbmOptions = {
        id: "tx_checkPwAjax",
        method: "post",
        action: "/main/login.do",
        ref: "dma_checkPwAjaxReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_emailCheck
 * @description email Check 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_emailCheck = async function () {
    const sbmOptions = {
        id: "tx_emailCheck",
        method: "post",
        action: "/account/registProc.do",
        ref: "dma_emailCheckReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_sendForm
 * @description send Form 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_sendForm = async function () {
    const sbmOptions = {
        id: "tx_sendForm",
        method: "post",
        action: "/account/registProc.do?method=registerProcess",
        ref: "dma_sendFormReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name openPwPop
 * @description open Pw Pop 처리
 * @returns {void}
 * @hidden N
 */
scwin.openPwPop = function () {
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — "
    (function(){ throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + "/account/pwPop.do?method=passwordPop", unresolved: "nav:" + "/account/pwPop.do?method=passwordPop" }; })();
};

/**
 * @method
 * @name cancel
 * @description cancel 처리
 * @returns {void}
 * @hidden N
 */
scwin.cancel = function () {
    confirmF("회원가입 신청을 취소 하시겠습니까?", async function() {
            await $c.win.alert('화면 이동 미완 — 목적지 미확인(as-is: /main/main.do). 전환 대상 화면이 확정되면 연결됩니다.');
    });
};

/**
 * @method
 * @name validationForm
 * @description validation Form 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.validationForm = async function () {
    const frm = (document.frmReg || { elements: [] });
    const usrBelngDepNm = $c.util.getComponent('ipt_usrBelngDepNm');
    const jobtitlNm = $c.util.getComponent('ipt_jobtitlNm');
    if (await scwin.checkRequired(usrBelngDepNm)) {
        return;
    }
    if (await scwin.checkRequired(jobtitlNm)) {
        return;
    }
    if (await scwin.checkRequired($c.util.getComponent('ipt_telNo1'))) {
        return;
    }
    if (await scwin.checkRequired($c.util.getComponent('ipt_telNo2'))) {
        return;
    }
    if (await scwin.checkRequired($c.util.getComponent('ipt_telNo3'))) {
        return;
    }
    if (await scwin.checkRequired($c.util.getComponent('ipt_cellphoneNo1'))) {
        return;
    }
    if (await scwin.checkRequired($c.util.getComponent('ipt_cellphoneNo2'))) {
        return;
    }
    if (await scwin.checkRequired($c.util.getComponent('ipt_cellphoneNo3'))) {
        return;
    }
    if (await scwin.checkRequired($c.util.getComponent('ipt_email1'))) {
        return;
    }
    if (await scwin.checkRequired($c.util.getComponent('ipt_email2'))) {
        return;
    }
    if (!(scwin.isNumberInput($c.util.getComponent('ipt_telNo1')) && scwin.isNumberInput($c.util.getComponent('ipt_telNo2')) && scwin.isNumberInput($c.util.getComponent('ipt_telNo3')))) {
        await alertE('유선전화번호는 숫자만 입력하십시오.');
        return;
    }
    if (!(scwin.isNumberInput($c.util.getComponent('ipt_cellphoneNo1')) && scwin.isNumberInput($c.util.getComponent('ipt_cellphoneNo2')) && scwin.isNumberInput($c.util.getComponent('ipt_cellphoneNo3')))) {
        await alertE('휴대전화번호는 숫자만 입력하십시오.');
        return;
    }
    if (!(scwin.isNumberInput($c.util.getComponent('ipt_faxNo1')) && scwin.isNumberInput($c.util.getComponent('ipt_faxNo2')) && scwin.isNumberInput($c.util.getComponent('ipt_faxNo3')))) {
        await alertE('FAX는 숫자만 입력하십시오.');
        return;
    }
    const hiddenEmail = $c.util.getComponent("ipt_hiddenEmail").getValue();
    const chgEmail = $c.str.trim($c.util.getComponent('ipt_email1').getValue()) + '@' + $c.str.trim($c.util.getComponent('ipt_email2').getValue());
    if (hiddenEmail !== chgEmail) {
        if ($c.util.getComponent("ipt_emailUseYn").getValue() !== chgEmail) {
            await alertE("이메일 중복여부를 확인하시기 바랍니다.");
            return;
        }
    }
    if (!scwin.checkPwAjax(frm)) {
        return;
    }
};

/**
 * @method
 * @name chngEmailBtn
 * @description chng Email Btn 처리
 * @returns {void}
 * @hidden N
 */
scwin.chngEmailBtn = function () {
    scwin.chgBtn.setStyle("display", "none");
    scwin.confBtn.setStyle("display", "");
    (($c.util.getComponent('ipt_email1')) && ($c.util.getComponent('ipt_email1')).setReadOnly ? ($c.util.getComponent('ipt_email1')).setReadOnly((false) === 'disabled' || (false) === 'readonly' || (false) === 'checked' ? true : (false)) : void 0);
    (($c.util.getComponent('ipt_email2')) && ($c.util.getComponent('ipt_email2')).setReadOnly ? ($c.util.getComponent('ipt_email2')).setReadOnly((false) === 'disabled' || (false) === 'readonly' || (false) === 'checked' ? true : (false)) : void 0);
    (($c.util.getComponent('ipt_email1')) && ($c.util.getComponent('ipt_email1')).removeClass ? ($c.util.getComponent('ipt_email1')).removeClass("bgcolor1") : console.error('[sdd] removeClass 미지원 컴포넌트: ipt_email1'));
    (($c.util.getComponent('ipt_email2')) && ($c.util.getComponent('ipt_email2')).removeClass ? ($c.util.getComponent('ipt_email2')).removeClass("bgcolor1") : console.error('[sdd] removeClass 미지원 컴포넌트: ipt_email2'));
};

/**
 * @method
 * @name alertE
 * @description alert E 처리
 * @param {String} msg 항목명
 * @param {*} callback callback
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.alertE = async function (msg, callback) {
    // as-is 는 화면 안 #pAlertText/#divAlertMsg 를 만졌다 — 엔진 프레임 접두 때문에
    // 그 선택자는 어디서도 못 찾는다. 표준 알림으로 낸다(메시지가 사라지지 않게).
    await $c.win.alert(msg);
    if (typeof callback === 'function') { await callback(); }
};

async function alertE(msg, callback) { return await scwin.alertE(msg, callback); }

// 억제된 trigger 함수의 as-is 이름 별칭 (호출자 정합)

/**
 * @method
 * @name checkRequired
 * @description 필수 입력 검사 — 값이 비면 항목명으로 알리고 포커스를 준 뒤 true(as-is fn_NullChk/fn_IsNull 의미 보존 · pcc/fil 반입 후보)
 * @param {Object} comp 입력 컴포넌트
 * @param {*} fieldName 항목명(생략 시 컴포넌트 title → id)
 * @returns {Promise<Boolean>} 비어 있으면 true
 * @hidden N
 */
scwin.checkRequired = async function (comp, fieldName) {
    if (!comp || !$c.util.isEmpty($c.str.trim(String(comp.getValue() ?? "")))) { return false; }
    const name = fieldName || (typeof comp.getTitle === "function" && comp.getTitle()) || comp.getID();
    await $c.win.alert("'" + name + "' 항목을 입력하세요");
    comp.focus();
    return true;
};

/**
 * @method
 * @name isNumberInput
 * @description 숫자만 입력됐는지 검사 — 아니면 포커스를 주고 false(as-is fn_IsNumber 의미 보존 · pcc/fil 반입 후보)
 * @param {Object} comp 입력 컴포넌트
 * @returns {Boolean} 숫자(공백 제외)만이면 true
 * @hidden N
 */
scwin.isNumberInput = function (comp) {
    const v = String(comp.getValue() ?? "").replace(/\s/g, "");
    if (!/^\d*$/.test(v)) { comp.focus(); return false; }
    return true;
};
